def current_rows(events):
    latest = {}
    for event in events:
        eid = event['id']
        key = (event['event_time'], event['seq'])
        if eid not in latest or key > latest[eid][0]:
            latest[eid] = (key, event['op'], event['value'])
    result = []
    for eid, (key, op, value) in latest.items():
        if op != 'D':
            result.append({'id': eid, 'value': value})
    result.sort(key=lambda x: x['id'])
